{
  "title": "未播完的歌",
  "synopsis": "老街广播站迎来修复后的首次街坊互动，一通热线翻出了当年没播完的旧歌。两人不再逃避，用完美的声音和坦诚的道歉共同补齐遗憾，在掌声与晨光中彻底完成双向治愈。",
  "preview_blurb": "老街广播站迎来修复后的首次街坊互动，一通热线却翻出了当年没播完的旧歌。面对曾经的遗憾，两人选择用声音共同补齐。",
  "scenes": [
    {
      "title": "热线里的旧账",
      "location": "老街广播站机房",
      "dramatic_goal": "接听街坊热线，直面当年未播完歌曲的情感考验，确立补全遗憾的行动目标。",
      "lines": [
        {
          "kind": "sfx",
          "text": "导播台老式电话铃声突兀响起，伴随着窗外街坊们聚集的嘈杂议论声与轻敲玻璃的动静。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "喂，王阿婆？对，早新闻马上开始。您说……好，好，我记下了。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "林岚，街角杂货铺的王阿婆打来热线。她问，当年因为事故没播完的那首《送别》，今天能补上吗？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "能。当年是外墙线路断了，今天线接好了。旧卡带我也清理干净了，随时能播。"
        }
      ]
    },
    {
      "title": "补齐的送别",
      "location": "老街广播站机房",
      "dramatic_goal": "通过广播坦诚当年的错误，在完美的设备状态支持下播完歌曲，实现情感与社区信任的双重修复。",
      "lines": [
        {
          "kind": "sfx",
          "text": "卡带推入卡槽的机械声，随后《送别》温暖的前奏在机房内响起。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "各位街坊，早安。我是周野。这几天，我和林岚手工飞线、找电位器，总算把这台老机器从鬼门关拉回来了。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "当年那首歌没唱完，是我太急躁，错怪了林岚。今天，这首完整的《送别》，送给老街，也送给我的搭档。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "阻抗完美匹配，高音单元运行平稳。周野，电位器锁死了，推子可以推满。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "好。让这干净的声音，替我们把当年的遗憾，一点点补齐。音乐，起。"
        }
      ]
    },
    {
      "title": "晨光中的闭环",
      "location": "老街广播站机房",
      "dramatic_goal": "在街坊的掌声中确认修复成果，翻过维修日志的旧页，以温暖的晨间广播彻底收束故事。",
      "lines": [
        {
          "kind": "sfx",
          "text": "歌曲尾声渐弱，窗外传来王阿婆带头的、参差不齐却真诚的掌声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "阿婆带头鼓掌了……林岚，你听，窗外的掌声真真切切，没有杂音，只有人情味。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "维修日志上，‘待校准’那一页翻过去了。现在写的是，运行完美。"
        },
        {
          "kind": "narration",
          "text": "晨光透过机房的玻璃，落在两人相视一笑的脸上。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "老街的早晨，以后我们都在。晨间背景乐，推子我推上去了。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "以后都在。早安，老街。"
        },
        {
          "kind": "sfx",
          "text": "推子推上的摩擦声，轻快温暖的晨间背景乐切入，伴随窗外的掌声渐渐淡出。"
        }
      ]
    }
  ],
  "episode_summary": "本集林岚与周野完成修复后的首次街坊互动广播。面对王阿婆点播的《送别》，两人不再逃避，周野在广播中坦诚当年的错误，林岚用完美的设备状态给予支持。歌曲圆满播完，街坊的掌声与晨光见证了两人彻底的双向治愈与社区信任的重建。",
